const ai = $json.output ?? {};
const article = $('Prepare Company Analysis').item.json;

const emptyValues = new Set([
  '',
  'empty',
  'unknown',
  'not mentioned',
  'not available',
  'n/a',
  'none',
  'null',
]);

function cleanNullable(value) {
  const text = String(value ?? '').trim();

  return emptyValues.has(text.toLowerCase())
    ? null
    : text;
}

function normalizeEnum(value, allowed, fallback) {
  const normalized = String(value ?? fallback)
    .trim()
    .toUpperCase();

  return allowed.includes(normalized)
    ? normalized
    : fallback;
}
function extractDomain(value) {
  const raw = String(value ?? '')
    .trim()
    .toLowerCase();

  if (!raw) {
    return '';
  }

  return raw
    .replace(/^[a-z][a-z0-9+.-]*:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .replace(/:\d+$/, '');
}

const recommendedRoles = Array.isArray(ai.recommended_roles)
  ? ai.recommended_roles
  : ai.recommended_roles
    ? [String(ai.recommended_roles)]
    : [];

const selectedWebsite =
  ai.company_website ||
  article.official_website ||
  '';

const companyDomain = extractDomain(selectedWebsite);

const fallbackCompanyKey = String(
  ai.company_name ?? ''
)
  .trim()
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

return {
  json: {
    article_url: article.article_url ?? '',
    article_title: article.title ?? '',
    published_at: article.published_at ?? '',
    country: article.country ?? '',
    source: article.source ?? '',

    official_website_scraped:
      article.official_website ?? '',

    company_name: ai.company_name ?? '',

    company_website: selectedWebsite,

    company_domain: companyDomain,

    company_key:
      companyDomain || fallbackCompanyKey,

    location: ai.location ?? '',
    sector: ai.sector ?? '',
    product_summary: ai.product_summary ?? '',

    funding_amount: ai.funding_amount ?? '',
    funding_stage: ai.funding_stage ?? '',

    hiring_signal: Boolean(ai.hiring_signal),
    hiring_evidence: ai.hiring_evidence ?? '',

    profile_fit_score: Number(
      ai.profile_fit_score ?? 0
    ),

    profile_fit_evidence:
      ai.profile_fit_evidence ?? '',

    profile_fit_inference:
      ai.profile_fit_inference ?? '',

    recommended_roles: recommendedRoles,
    outreach_angle: ai.outreach_angle ?? '',

    visa_support_status: normalizeEnum(
      ai.visa_support_status,
      ['UNKNOWN', 'POSSIBLE', 'EXPLICIT'],
      'UNKNOWN'
    ),

    visa_sponsorship_evidence:
      cleanNullable(ai.visa_sponsorship_evidence),

    research_priority: normalizeEnum(
      ai.research_priority,
      ['HIGH', 'MEDIUM', 'LOW'],
      'LOW'
    ),

    confidence_score: Number(
      ai.confidence_score ?? 0
    ),

    entity_type: normalizeEnum(
      ai.entity_type,
      [
        'STARTUP',
        'SCALEUP',
        'VC_FUND',
        'ACCELERATOR',
        'CORPORATE',
        'OTHER',
      ],
      'OTHER'
    ),

    entity_type_evidence:
      ai.entity_type_evidence ?? '',

    verified_company_country:
      ai.verified_company_country ?? '',

    country_match_status: normalizeEnum(
      ai.country_match_status,
      ['MATCH', 'MISMATCH', 'UNCERTAIN'],
      'UNCERTAIN'
    ),

    direct_employer_priority: normalizeEnum(
      ai.direct_employer_priority,
      ['HIGH', 'MEDIUM', 'LOW'],
      'LOW'
    ),

    ecosystem_value: normalizeEnum(
      ai.ecosystem_value,
      ['HIGH', 'MEDIUM', 'LOW'],
      'LOW'
    ),

    recommended_action:
      ai.recommended_action ?? '',

    analysis_version: 2,
    pipeline_status: 'RESEARCHED',
  },
};

function normalizeUrl(value) {
  const raw = String(value ?? '').trim();

  if (!raw) {
    return '';
  }

  try {
    const url = new URL(raw);

    // Ignore fragments/query strings for deduplication.
    url.hash = '';
    url.search = '';

    return (
      url.origin +
      url.pathname.replace(/\/+$/, '')
    ).toLowerCase();
  } catch {
    return raw
      .replace(/[?#].*$/, '')
      .replace(/\/+$/, '')
      .toLowerCase();
  }
}


// URLs already stored in Companies
const existingUrls = new Set(
  $('Load Existing Articles')
    .all()
    .map(item =>
      normalizeUrl(item.json.article_url)
    )
    .filter(Boolean)
);


// Also protect against duplicates inside
// the CURRENT discovery execution.
const seenThisRun = new Set();

const output = [];

for (const item of $input.all()) {
  const url = normalizeUrl(
    item.json.article_url
  );

  if (!url) {
    continue;
  }

  // Already processed previously
  if (existingUrls.has(url)) {
    continue;
  }

  // Duplicate returned during this run
  if (seenThisRun.has(url)) {
    continue;
  }

  seenThisRun.add(url);

  output.push({
    json: {
      ...item.json,
    },
  });
}

return output;

const cutoff = new Date();
cutoff.setMonth(cutoff.getMonth() - 24);

return $input.all().filter(item => {
  const publishedAt = String(
    item.json.published_at ?? ''
  ).trim();

  if (!publishedAt) {
    // Keep it if date extraction failed.
    // Better to inspect it later than silently lose it.
    return true;
  }

  const publishedDate = new Date(publishedAt);

  if (Number.isNaN(publishedDate.getTime())) {
    return true;
  }

  return publishedDate >= cutoff;
});
